#!/usr/bin/env python3
"""Generate assembly profiles and the device reference from devices.json.

The database is input only. --check verifies generated outputs without writes.
"""
import argparse
from pathlib import Path
import sys

import device_database as database

ROOT = Path(__file__).resolve().parent
TABLE_PATH = ROOT.parents[2] / 'docs/mini/DEVICES.md'


def render_table(devices):
    lines = ['# Optiboot Mini device reference', '',
             '<!-- Generated by gen_devices.py from devices.json; do not edit. -->', '',
             'Device values describe the current software profiles. They do not establish',
             'physical qualification. Clock ratings remain subject to datasheet voltage limits.', '',
             'See the [database maintenance guide](DEVICE_DATABASE.md) for schema and updates.', '',
             '| MCU | Signature | Flash B | EEPROM B | Page / erase B | SRAM end | Architecture | Max MHz | Min Boot B | Editions |',
             '|---|---|---:|---:|---:|---|---|---:|---|---|']
    profiles = 0
    for name, dev in devices.items():
        editions = database.available_editions(dev)
        profiles += len(editions)
        signature = ' '.join(f'{byte:02X}' for byte in dev['sig'])
        minimum = dev['hardware_min_boot_bytes'] if not dev['virtual_boot'] else 'Virtual'
        lines.append(f'| `{name}` | `{signature}` | {dev["flash"]} | {dev["eeprom"]} | '
                     f'{dev["page"]} / {dev["flash_erase_group_bytes"]} | `0x{dev["ramend"]:04X}` | '
                     f'`{dev["profile"]}` | {dev["max_mhz"]} | {minimum} | '
                     + ', '.join(f'`{edition}`' for edition in editions) + ' |')
    lines += ['', f'{len(devices)} devices; {profiles} edition/device profiles.', '',
              'Mini reserves 256 bytes. Middle reserves 512 bytes on eligible ATmega and',
              '1024 bytes on Virtual ATtiny. Full reserves 1024 bytes. SRAM end is an',
              'address, not a RAM capacity. Virtual Boot has no hardware BOOTSZ section.', '']
    return '\n'.join(lines)


def generate(output_dir, table_path, check=False):
    devices = database.DEVICES
    outputs = {Path(output_dir)/(name+'.inc'): database.render_device(name, dev)
               for name, dev in devices.items()}
    outputs[Path(output_dir)/'select.inc'] = database.render_selector(devices)
    outputs[Path(table_path)] = render_table(devices)
    stale = []
    for path, text in outputs.items():
        if check:
            if not path.is_file() or path.read_text(encoding='utf-8') != text:
                stale.append(path.name)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding='utf-8')
    stale += [path.name for path in Path(output_dir).glob('*.inc') if path not in outputs]
    if stale:
        raise ValueError('Stale or unexpected generated files: '+', '.join(stale))
    return len(devices)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Read-only consistency check')
    parser.add_argument('--output-dir', type=Path, default=ROOT/'devices')
    parser.add_argument('--table-output', type=Path, default=TABLE_PATH)
    args = parser.parse_args(argv)
    try:
        count = generate(args.output_dir, args.table_output, args.check)
        print(f'{"Checked" if args.check else "Generated"} {count} AVR device profiles and device reference')
        return 0
    except (ValueError, OSError) as error:
        print('ERROR:', error, file=sys.stderr)
        return 2


if __name__ == '__main__':
    sys.exit(main())
